"""Android phone player settings sheet: grouped rows, inline switches write the same stored values, back steps one page, text pages apply or cancel. Optional arg: screenshot dir."""
from pathlib import Path
from playwright.sync_api import sync_playwright
import tempfile, subprocess, json, sys
root=Path(__file__).resolve().parents[1]
shots=Path(sys.argv[1]) if len(sys.argv)>1 else None
checks=[]
def check(name,ok,detail=None):
    checks.append(dict(name=name,passed=bool(ok),detail=detail));assert ok,(name,detail)
FITS='e=>{const r=e.getBoundingClientRect();return e.scrollHeight<=e.clientHeight+1&&r.top>=0&&r.bottom<=innerHeight+1&&r.left>=0&&r.right<=innerWidth+1}'
with tempfile.TemporaryDirectory(prefix='seanime-player-settings-') as tmp:
    bundle=Path(tmp)/'settings.js'
    subprocess.run(['node',str(root/'tests/mobile_anime_bundle.cjs'),str(bundle),'mobile_player_settings_harness.tsx','--no-stubs'],check=True,cwd=root)
    with sync_playwright() as pw:
        browser=pw.chromium.launch(headless=True)
        def open_page(width,height,lang='en'):
            page=browser.new_page(viewport=dict(width=width,height=height),device_scale_factor=3,has_touch=True,is_mobile=True)
            page.route('http://anime.test/**',lambda r:r.fulfill(content_type='text/html',body='<html class="dark"><head><meta name="viewport" content="width=device-width,initial-scale=1"></head><body><div id="root"></div></body></html>'))
            # Server stand-in for PATCH /api/v1/settings/path: applies {path,value} to mediaPlayer and answers with the status.
            page.patches=[];page.media_player=dict(vcTranslate=False,vcTranslateProvider='',vcTranslateTargetLanguage='',vcTranslateApiKey='',vcTranslateBaseUrl='',vcTranslateModel='')
            def settings_path(r):
                cors={'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'PATCH, OPTIONS','Access-Control-Allow-Headers':'*'}
                if r.request.method=='OPTIONS': return r.fulfill(status=204,headers=cors)
                body=json.loads(r.request.post_data);page.patches.append((r.request.method,body['path'],body['value']))
                page.media_player[body['path'].split('.',1)[1]]=body['value']
                r.fulfill(status=200,headers=cors,content_type='application/json',body=json.dumps({'data':{'settings':{'mediaPlayer':page.media_player}}}))
            page.route('**/api/v1/settings/path',settings_path)
            page.goto('http://anime.test/')
            page.evaluate('localStorage.setItem("sea-media-core-preferences",JSON.stringify({version:2,autoPlay:true,autoNext:true,autoSkip:false,playbackRate:1,volumeBoost:1}));localStorage.setItem("seanime-mobile-language",JSON.stringify("'+lang+'"))')
            page.reload()
            for css in (root/'backend/seanime-web/out/static/css').rglob('*.css'):page.add_style_tag(path=str(css))
            page.add_style_tag(path=str(bundle.with_suffix('.css')));page.add_script_tag(path=str(bundle))
            page.locator('#player button').first.wait_for()
            return page
        def open_sheet(page):
            page.locator('#player button').first.tap()
            sheet=page.locator('.vc-phone-settings');sheet.wait_for();page.wait_for_timeout(250)
            return sheet
        stored_delay=lambda page:page.evaluate('JSON.parse(localStorage.getItem("sea-video-core-settings")||"{}").subtitleDelay')
        pref=lambda page,key:page.evaluate(f'JSON.parse(localStorage.getItem("sea-media-core-preferences")||"{{}}")["{key}"]')

        page=open_page(360,740);sheet=open_sheet(page)
        groups=sheet.locator('.vc-phone-group-title').all_inner_texts()
        check('Phone sheet shows grouped settings',groups==['Playback','Language & subtitles','Display'] and sheet.get_by_role('heading',name='Player settings').count()==1,groups)
        heights=sheet.locator('.vc-phone-row').evaluate_all('rows=>rows.map(r=>Math.round(r.getBoundingClientRect().height))')
        check('Every row is a 48 dp+ touch target',len(heights)==13 and min(heights)>=48,heights)
        rows=sheet.locator('.vc-phone-row-label').all_inner_texts()
        check('Desktop-only Anime4K and Preferences are not offered on phones','Anime4K' not in rows and 'Preferences' not in rows,rows)
        # 360x740 is short for 12 rows: the docked sheet stays on screen and scrolls inside; 390x844 below fits whole.
        check('Portrait 360x740: sheet stays on screen, the last row is reachable inside it',sheet.evaluate('e=>{const r=e.getBoundingClientRect();e.scrollTop=e.scrollHeight;const l=e.querySelector(".vc-phone-group:last-child .vc-phone-row:last-child").getBoundingClientRect();const ok=r.top>=0&&r.bottom<=innerHeight+1&&l.bottom<=r.bottom+1;e.scrollTop=0;return ok}'))
        check('New rows: libass, subtitle blacklist and skip patterns (EN)',all(l in rows for l in ('Subtitle renderer: libass','Subtitle blacklist','Skip patterns')),rows)
        check('Values are readable in their rows',sheet.locator('.vc-phone-row',has_text='Speed').inner_text().split('\n')[-1]=='1.00x' and sheet.locator('.vc-phone-row',has_text='Delay').inner_text().endswith('0.0 s'))
        if shots: page.screenshot(path=str(shots/'harness-settings-portrait.png'))
        for label,key in (('Auto play','autoPlay'),('Auto next','autoNext'),('Skip OP/ED','autoSkip')):
            switch=sheet.get_by_role('switch',name=label);before=pref(page,key)
            check(f'{label}: switch mirrors the stored value',switch.get_attribute('aria-checked')==('true' if before else 'false'),before)
            switch.tap()
            check(f'{label}: switch writes the same stored setting',pref(page,key) is (not before) and switch.get_attribute('aria-checked')==('false' if before else 'true') and sheet.is_visible())
            switch.tap()
            check(f'{label}: second tap restores it',pref(page,key) is before)
        sheet.locator('.vc-phone-row',has_text='Speed').tap()
        back=sheet.locator('[data-vc-element="menu-section-close"]');back.wait_for()
        check('Speed opens its page with a clear back row',back.inner_text().strip()=='Playback speed' and back.evaluate('e=>e.getBoundingClientRect().height')>=48)
        sheet.get_by_role('button',name='1.5',exact=True).tap()
        check('Speed page sets the stored playback rate',pref(page,'playbackRate')==1.5)
        sheet.get_by_role('button',name='1.0',exact=True).tap()
        if shots: page.screenshot(path=str(shots/'harness-settings-speed.png'))
        page.keyboard.press('Escape');page.wait_for_timeout(150)
        check('Back on a sub page returns to the overview',sheet.is_visible() and sheet.locator('[data-vc-phone-settings="home"]').count()==1)
        sheet.locator('.vc-phone-row',has_text='Delay').tap()
        sheet.get_by_role('button',name='+0.1',exact=True).tap()
        check('Subtitle delay page still saves through the subtitle manager',page.evaluate('subtitleUpdates')>=1)
        sheet.get_by_role('button',name='−0.1',exact=True).tap()
        preset=lambda label:sheet.locator('[data-vc-element="setting-select"]').get_by_role('button',name=label,exact=True)
        chosen=lambda label:preset(label).locator('[data-vc-element="setting-select-option-indicator"] svg').count()==1
        preset('1.0s').tap()
        check('Subtitle delay: the 1.0s preset shows as chosen',chosen('1.0s') and stored_delay(page)==1 and not chosen('0.5s') and not chosen('-1.0s'))
        preset('0s').tap()
        check('Subtitle delay: 0s preset restores it',chosen('0s') and not chosen('1.0s') and stored_delay(page)==0)
        page.keyboard.press('Escape');page.wait_for_timeout(150)
        libass=lambda:page.evaluate('localStorage.getItem("sea-video-core-use-libass-renderer")')
        switch=sheet.get_by_role('switch',name='Subtitle renderer: libass');updates=page.evaluate('subtitleUpdates')
        check('libass: switch shows the default (on)',switch.get_attribute('aria-checked')=='true',libass())
        switch.tap()
        check('libass: switch writes sea-video-core-use-libass-renderer like the preferences modal',libass()=='false' and switch.get_attribute('aria-checked')=='false' and sheet.is_visible())
        switch.tap()
        check('libass: second tap restores it; like desktop it only stores the value (applies on the next stream load)',libass()=='true' and page.evaluate('subtitleUpdates')==updates)
        stored=lambda key:page.evaluate(f'JSON.parse(localStorage.getItem("sea-video-core-settings")||"{{}}")["{key}"]')
        def editor(label,title):
            sheet.locator('.vc-phone-row',has_text=label).tap()
            back=sheet.locator('[data-vc-element="menu-section-close"]');back.wait_for()
            field=sheet.locator('input.vc-phone-input')
            check(f'{label}: opens its own page with the field',back.inner_text().strip()==title and field.count()==1)
            return field
        def targets(): return sheet.locator('[data-vc-element="menu-section-close"], input.vc-phone-input, .vc-phone-editor-actions button').evaluate_all('e=>e.map(x=>Math.round(x.getBoundingClientRect().height))')
        blacklist0=stored('preferredSubtitleBlacklist') or ''
        field=editor('Subtitle blacklist','Subtitle blacklist')
        h=targets();check('Blacklist page: back row, field, Cancel and Apply are 48 dp+',len(h)==4 and min(h)>=48,h)
        field.fill('signs & songs,signs/songs');sheet.get_by_role('button',name='Cancel',exact=True).tap();page.wait_for_timeout(150)
        check('Blacklist: Cancel leaves the stored value and returns to the overview',(stored('preferredSubtitleBlacklist') or '')==blacklist0 and sheet.locator('[data-vc-phone-settings="home"]').count()==1)
        field=editor('Subtitle blacklist','Subtitle blacklist')
        check('Blacklist: the page starts from the stored value again',field.input_value()==blacklist0)
        field.fill('signs & songs,signs/songs');page.keyboard.press('Escape');page.wait_for_timeout(150)
        check('Blacklist: Back discards the draft',(stored('preferredSubtitleBlacklist') or '')==blacklist0 and sheet.locator('[data-vc-phone-settings="home"]').count()==1)
        field=editor('Subtitle blacklist','Subtitle blacklist');updates=page.evaluate('subtitleUpdates')
        field.fill('signs & songs,signs/songs')
        if shots: page.screenshot(path=str(shots/'harness-settings-blacklist.png'))
        sheet.get_by_role('button',name='Apply',exact=True).tap();page.wait_for_timeout(150)
