        sheet.get_by_role('button',name='Cancel',exact=True).tap();page.wait_for_timeout(150)
        check('Skip patterns: Cancel leaves the stored value',skip()==skip0 and sheet.locator('[data-vc-phone-settings="home"]').count()==1,skip())
        field=editor('Skip patterns','Skip patterns')
