        check('Skip patterns row shows how many patterns are set',sheet.locator('.vc-phone-row',has_text='Skip patterns').inner_text().split('\n')[-1]=='1')
        field=editor('Skip patterns','Skip patterns');field.fill('');sheet.get_by_role('button',name='Apply',exact=True).tap();page.wait_for_timeout(150)
        check('Skip patterns: clearing them stores an empty value and the row says None',skip()=='' and sheet.locator('.vc-phone-row',has_text='Skip patterns').inner_text().split('\n')[-1]=='None')
